error MissingUser { id: string }

effect function find(id: string) {
  if (id === "missing") throw new MissingUser({ id })
  return `Hello, ${id}!`
}

effect function main() {
  try Console.log(try find("Ada"))
  const guest = find("missing") catch () => "Hello, guest!"
  try Console.log(guest)
}

await runPromise(main())

service Greeting { prefix: string }
const GreetingLive = Layer.succeed(Greeting, { prefix: "Hello" })

effect function main() {
  provide GreetingLive {
    const greeting = try Greeting
    try Console.log(`${greeting.prefix}, Ada!`)
  }
}

await runPromise(main())

data Delivery { Waiting; Sent { tracking: string } }

function describe(delivery: Delivery) {
  return match (delivery) {
    when { _tag: "Waiting" }: "waiting";
    when { _tag: "Sent", let tracking }: `sent:${tracking}`;
  }
}

effect function main() {
  try Console.log(describe(Delivery.Waiting()))
  try Console.log(describe(Delivery.Sent({ tracking: "parcel-7" })))
}

await runPromise(main())
